import * as T from './vendor/three.module.min.js';
const won=n=>n.toLocaleString('ko-KR')+'원';
export class Checkout {
 constructor({state,canvas,onChange,onClose,onReceipt,sound}){Object.assign(this,{state,canvas,onChange,onClose,onReceipt,sound});this.active=false;this.drag=null;this.scene=new T.Scene();this.scene.background=new T.Color('#dce2d6');this.scene.add(new T.HemisphereLight(0xfff4dc,0x758b79,3));const light=new T.DirectionalLight(0xffffff,2);light.position.set(-3,6,4);this.scene.add(light);this.camera=new T.OrthographicCamera(-2,2,2,-2,.1,30);this.camera.position.set(0,5,3.7);this.camera.lookAt(0,.2,0);this.ray=new T.Raycaster();this.pointer=new T.Vector2();
 const material=c=>new T.MeshStandardMaterial({color:c,roughness:.6});const mesh=(g,c,x,y,z,parent=this.scene)=>{const m=new T.Mesh(g,material(c));m.position.set(x,y,z);parent.add(m);return m};this.box=(w,h,d,c,x,y,z,p)=>mesh(new T.BoxGeometry(w,h,d),c,x,y,z,p);
 this.box(3.4,.18,2.1,0xbf9c72,0,-.12,0);this.box(.9,.1,.55,0x466a56,.45,.03,.65);for(const [x,z,w,d]of [[0,.65,.04,.55],[.9,.65,.04,.55],[.45,.38,.9,.04],[.45,.92,.9,.04]])this.box(w,.12,d,0x315440,x,.09,z);
 this.terminal=this.box(.66,.25,.85,0x354b40,.83,.12,-.46);this.screen=this.box(.48,.025,.37,0xb2c7a3,.83,.26,-.62);for(const x of [.65,.82,.99])for(const z of [-.35,-.19])this.box(.09,.025,.07,0xe5e2cc,x,.26,z);this.box(.5,.06,.38,0xd6a780,-.98,.04,-.58);this.box(.24,.07,.7,0x809581,-1.05,.02,-1.0);
 this.home=new T.Vector3(-.95,.14,-.5);this.till=new T.Vector3(.45,.16,.65);this.changeHome=new T.Vector3(-.2,.18,.65);this.terminalPoint=new T.Vector3(.83,.3,-.46);
 this.box(.5,.28,.42,0x526258,-.1,.15,-.17);this.box(.42,.018,.05,0x182f24,-.1,.3,.03);this.receiptHome=new T.Vector3(-.1,.32,.28);this.receipt=new T.Group();this.scene.add(this.receipt);this.receipt.visible=false;
 this.cash=new T.Group();this.scene.add(this.cash);this.card=new T.Group();this.scene.add(this.card);this.makePaper(this.card,'CAFÉ CARD','체험용 카드',0x426a82,.64,.4);this.change=new T.Group();this.scene.add(this.change);this.change.position.copy(this.changeHome);this.cash.position.copy(this.home);this.card.position.copy(this.home);
 document.body.insertAdjacentHTML('beforeend',`<section id="checkout" hidden aria-label="직접 계산하기"><header><small>HANDS ON / CHECKOUT</small><h2>한 잔의 값을 주고받아요</h2><button id="payExit">카페로 ↗</button></header><div id="payOrder"></div><p id="payHint" role="status"></p><span id="payGuest">손님 손 · 여기에 건네기</span><span id="payTarget"></span><div id="receiptThanks" hidden role="status"></div><span id="payReceipt" hidden>영수증 · 손님에게 끌기</span><span id="payChange">거스름돈 · 손님에게 끌기</span><footer><div id="payTotals"></div><div id="payCoins"><button data-money="5000">5,000원</button><button data-money="1000">1,000원</button><button data-money="500">500원</button><button data-money="100">100원</button><button id="payUndo">하나 빼기 ↶</button></div><small>체험용 가상 결제 · 실제 돈이 오가지 않아요</small><button id="payDone" hidden>결제 완료 · 커피 만들러 가기 →</button></footer></section>`);
 this.el=id=>document.getElementById(id);this.el('payExit').onclick=()=>this.close();this.el('payDone').onclick=()=>this.close();document.querySelectorAll('[data-money]').forEach(b=>b.onclick=()=>{if(this.model.add(Number(b.dataset.money))){this.rebuildChange();this.refresh();this.sound(500,.04)}});this.el('payUndo').onclick=()=>{this.model.undo();this.rebuildChange();this.refresh()};canvas.addEventListener('pointerdown',e=>this.down(e));canvas.addEventListener('pointermove',e=>this.move(e));canvas.addEventListener('pointerup',e=>this.up(e));canvas.addEventListener('pointercancel',e=>this.up(e,true));canvas.addEventListener('lostpointercapture',e=>this.up(e,true));window.addEventListener('blur',()=>this.cancel());document.addEventListener('visibilitychange',()=>{if(document.hidden)this.cancel()});
 }
 makePaper(parent,title,subtitle,color,w=.74,d=.36){this.box(w,.028,d,color,0,.015,0,parent);const c=document.createElement('canvas');c.width=512;c.height=256;const ctx=c.getContext('2d');ctx.fillStyle=color===0x426a82?'#fff9e9':'#284c39';ctx.textAlign='center';ctx.font='bold 62px sans-serif';ctx.fillText(title,256,110);ctx.font='30px sans-serif';ctx.fillText(subtitle,256,185);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;const m=new T.Mesh(new T.PlaneGeometry(w*.95,d*.95),new T.MeshBasicMaterial({map:tex,transparent:true}));m.rotation.x=-Math.PI/2;m.position.y=.031;parent.add(m)}
 clearGroup(g){for(const m of [...g.children]){g.remove(m);m.traverse(o=>{o.geometry?.dispose();if(o.material){o.material.map?.dispose();o.material.dispose()}})}}
 rebuildChange(){this.clearGroup(this.change);this.model.change.forEach((v,i)=>{const g=new T.Group();g.position.set((i%3-.8)*.13,Math.floor(i/3)*.045,0);g.scale.setScalar(.7);this.change.add(g);if(v>=1000)this.makePaper(g,won(v),'거스름돈',v===5000?0xcba575:0x9abccc);else{const m=new T.Mesh(new T.CylinderGeometry(.2,.2,.035,24),new T.MeshStandardMaterial({color:v===500?0xd0bd84:0xc0c7c0,metalness:.4}));g.add(m)}})}
 open(){this.model=this.state.payment;if(!this.model)return;this.active=true;this.drag=null;this.thanked=false;this.clearGroup(this.cash);this.makePaper(this.cash,won(this.model.tender),'체험용 지폐',0xd3ae76);this.cash.position.copy(this.home);this.card.position.copy(this.model.paid?this.terminalPoint:this.home);this.change.position.copy(this.changeHome);this.rebuildChange();this.clearGroup(this.receipt);this.makePaper(this.receipt,this.state.order.drink,won(this.model.price)+' · '+(this.model.method==='card'?'카드':'현금'),0xfff9e9,.45,.68);this.receipt.position.copy(this.receiptHome);this.resize();this.el('checkout').hidden=false;document.body.classList.add('payOpen');this.refresh()}
 close(){this.cancel();this.active=false;this.el('checkout').hidden=true;document.body.classList.remove('payOpen');this.onClose();if(this.model.receiptGiven&&!this.thanked){this.thanked=true;this.onReceipt?.()}}
 cancel(){if(this.drag)this.drag.object.position.copy(this.drag.start);this.drag=null}
 resize(){const a=innerWidth/innerHeight,h=Math.max(1.75,1.8/a);this.camera.left=-h*a;this.camera.right=h*a;this.camera.top=h;this.camera.bottom=-h;this.camera.updateProjectionMatrix()}
 point(e){const b=this.canvas.getBoundingClientRect();this.pointer.set((e.clientX-b.left)/b.width*2-1,1-(e.clientY-b.top)/b.height*2);this.ray.setFromCamera(this.pointer,this.camera);return this.ray.ray.intersectPlane(new T.Plane(new T.Vector3(0,1,0),-.2),new T.Vector3())}
 down(e){if(!this.active||this.model.receiptGiven||this.drag)return;const kind=this.model.paid?(this.model.printProgress>=1?'receipt':null):this.model.method==='card'?'card':!this.model.received?'cash':this.model.change.length?'change':null;if(!kind)return;const object=this[kind],p=this.point(e);if(!p||Math.hypot(p.x-object.position.x,p.z-object.position.z)>.5)return;e.preventDefault();this.canvas.setPointerCapture(e.pointerId);this.drag={id:e.pointerId,kind,object,start:object.position.clone(),offset:{x:p.x-object.position.x,z:p.z-object.position.z}}}
 move(e){if(this.drag?.id!==e.pointerId)return;const p=this.point(e);if(!p)return;this.drag.object.position.set(T.MathUtils.clamp(p.x-this.drag.offset.x,-1.4,1.4),.25,T.MathUtils.clamp(p.z-this.drag.offset.z,-.8,.9))}
 up(e,cancelled=false){if(this.drag?.id!==e.pointerId)return;const {kind,object,start}=this.drag;let ok=false,warning='';if(!cancelled){if(kind==='receipt'&&object.position.distanceTo(this.home)<.5){ok=this.model.handReceipt();if(ok)this.sound(780,.12)}if(kind==='cash'&&object.position.distanceTo(this.till)<.5){ok=this.model.receive();this.sound(560,.1)}if(kind==='card'&&object.position.distanceTo(this.terminalPoint)<.5){ok=this.model.tap();if(ok){object.position.copy(this.terminalPoint);this.sound(1046,.18)}}if(kind==='change'&&object.position.distanceTo(this.home)<.5){ok=this.model.give();if(!ok)warning='거스름돈이 '+(this.model.selected<this.model.due?'부족해요.':'많아요.')+' 금액을 확인하고 다시 골라주세요.';else this.sound(880,.15)}}if(!ok)object.position.copy(start);this.drag=null;if(this.model.paid)this.state.completePayment();this.onChange();this.refresh();if(warning)this.el('payHint').textContent=warning}
 refresh(){const p=this.model;this.cash.visible=p.method==='cash'&&!p.received;this.card.visible=p.method==='card';this.change.visible=p.method==='cash'&&p.received&&!p.paid;this.screen.material.color.set(p.paid?0x71bb8b:0xb2c7a3);this.el('payOrder').textContent=this.state.order.name+' 님 · '+this.state.order.drink+' · '+won(p.price)+' / '+(p.method==='cash'?'현금':'카드');this.el('payHint').textContent=p.receiptGiven?'영수증까지 건넸어요. 이제 커피를 준비해요.':p.paid?(p.printProgress<1?'결제 완료 · 영수증을 출력하고 있어요…':'출력된 영수증을 잡아 손님 손으로 끌어 건네주세요.'):p.method==='card'?'손님의 카드를 잡아 오른쪽 단말기에 대세요.':!p.received?'손님이 낸 '+won(p.tender)+' 지폐를 오른쪽 돈 받는 곳으로 끌어 받으세요.':'아래에서 거스름돈을 고른 뒤, 돈 묶음을 손님 손으로 끌어 건네세요.';this.el('payTotals').textContent=p.method==='cash'?'받은 돈 '+won(p.received?p.tender:0)+' · 거스름돈 '+won(p.due)+' / 고른 돈 '+won(p.selected):p.paid?won(p.price)+' · 카드 승인 완료':won(p.price)+' · 카드 대기 중';this.el('payCoins').hidden=p.method!=='cash'||!p.received||p.paid;this.el('payDone').hidden=!p.receiptGiven;this.el('payDone').textContent='영수증 전달 완료 · 커피 만들러 →';this.receipt.visible=p.paid&&!p.receiptGiven;this.el('payReceipt').hidden=!p.paid||p.receiptGiven||p.printProgress<1;this.el('receiptThanks').hidden=!p.receiptGiven;this.el('receiptThanks').innerHTML='<small>'+this.state.order.name+' 님</small>영수증 잘 받았어요.<br>고맙습니다!';this.el('payTarget').textContent=p.method==='card'?'카드 단말기 · 여기에 대기':'돈 받는 곳';this.el('payGuest').hidden=p.receiptGiven;this.el('payChange').hidden=p.method!=='cash'||!p.received||!p.change.length||p.paid;this.el('payTarget').hidden=p.paid||(p.method==='cash'&&p.received);this.el('payUndo').disabled=p.paid||!p.change.length}
 update(dt=.016){const before=this.model.printProgress;this.model.print(dt);if(!this.drag||this.drag.kind!=='receipt')this.receipt.scale.z=Math.max(.01,this.model.printProgress);if(before!==this.model.printProgress)this.refresh();for(const [id,p,offset]of [['receiptThanks',this.home,45],['payReceipt',this.receiptHome,62],['payGuest',this.home,40],['payChange',this.changeHome,58],['payTarget',this.model.method==='card'?this.terminalPoint:this.till,50]]){const q=p.clone().project(this.camera);this.el(id).style.left=Math.max(95,Math.min(innerWidth-95,(q.x*.5+.5)*innerWidth))+'px';this.el(id).style.top=(-q.y*.5+.5)*innerHeight+offset+'px'}}
}
